out=Path(__file__).with_name('boundary_disagreement_qc.ipynb')
code1="from pathlib import Path\nimport pandas as pd, numpy as np\nimport matplotlib.pyplot as plt\nimport seaborn as sns\nfrom IPython.display import display\nRESULT_ROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/native_surface_analysis')\nTEMPLATE='fsaverage6'\nsf=sorted(RESULT_ROOT.glob(f'boundary_disagreement_{TEMPLATE}_D*/tables/boundary_agreement_summary.csv'))\nhf=sorted(RESULT_ROOT.glob(f'boundary_disagreement_{TEMPLATE}_D*/tables/boundary_agreement_by_hop.csv'))\nsummary=pd.concat([pd.read_csv(p) for p in sf],ignore_index=True)\nby_hop=pd.concat([pd.read_csv(p) for p in hf],ignore_index=True)\nprint(f'subjects={summary.subject_id.nunique():,}; rows={len(summary):,}; template={TEMPLATE}')\ndisplay(summary.head())"
code2="sum_cols=['valid_mappings','disagreements','boundary_near_mappings','boundary_near_disagreements','internal_mappings','internal_disagreements']\ncohort=summary[sum_cols].sum(axis=0)\ncohort['overall_disagreement_pct']=100*cohort['disagreements']/cohort['valid_mappings']\ncohort['boundary_near_disagreement_pct']=100*cohort['boundary_near_disagreements']/cohort['boundary_near_mappings']\ncohort['internal_disagreement_pct']=100*cohort['internal_disagreements']/cohort['internal_mappings']\ndisplay(cohort.to_frame().T.round(3))"
code3="plot_df=pd.DataFrame({'Location':['Boundary-near (≤2 hops)','Internal (>2 hops)'],'Disagreement (%)':[cohort.boundary_near_disagreement_pct,cohort.internal_disagreement_pct]})\nfig,ax=plt.subplots(figsize=(4,3)); sns.barplot(data=plot_df,x='Location',y='Disagreement (%)',color='#0072B2',ax=ax); ax.set_title('Label disagreement by surface location'); ax.set_xlabel(''); ax.spines[['top','right']].set_visible(False); fig.tight_layout(); plt.show()"
code4="low_agreement=summary.sort_values('disagreement_pct',ascending=False).head(30)\ndisplay(low_agreement[['subject_id','hemisphere','region','valid_mappings','disagreement_pct','boundary_near_disagreement_pct','internal_disagreement_pct','disagreements_near_boundary_pct']].round(2))\nfig,ax=plt.subplots(figsize=(5,4)); sns.scatterplot(data=summary,x='internal_disagreement_pct',y='boundary_near_disagreement_pct',hue='hemisphere',alpha=.55,s=22,ax=ax); ax.set_xlabel('Internal disagreement (%)'); ax.set_ylabel('Boundary-near disagreement (%)'); ax.set_title('Boundary versus internal disagreement'); ax.spines[['top','right']].set_visible(False); plt.show()"
code5="hop=by_hop.groupby('hop_bin',as_index=False).agg(valid_mappings=('valid_mappings','sum'),disagreements=('disagreements','sum'))\nhop['disagreement_pct']=100*hop.disagreements/hop.valid_mappings\ndisplay(hop.round(2))\nfig,ax=plt.subplots(figsize=(5.5,3.2)); sns.lineplot(data=hop,x='hop_bin',y='disagreement_pct',marker='o',color='#D55E00',ax=ax); ax.set_xlabel('Distance from native ROI boundary (surface hops)',labelpad=7); ax.set_ylabel('Disagreement (%)'); ax.spines[['top','right']].set_visible(False); fig.tight_layout(pad=1.2); plt.show()"
code6="display(summary[['invalid_target_labels','unknown_native_labels']].sum().to_frame('count').T)\nprint('Rows with invalid target labels:',int((summary.invalid_target_labels>0).sum()))\nprint('Rows with unknown native labels:',int((summary.unknown_native_labels>0).sum()))"
code7="region_stats=summary.groupby('region').agg(valid_mappings=('valid_mappings','sum'),disagreements=('disagreements','sum'),boundary_near_mappings=('boundary_near_mappings','sum'),boundary_near_disagreements=('boundary_near_disagreements','sum'),internal_mappings=('internal_mappings','sum'),internal_disagreements=('internal_disagreements','sum'))\nregion_stats['boundary_near_pct']=100*region_stats.boundary_near_disagreements/region_stats.boundary_near_mappings\nregion_stats['internal_pct']=100*region_stats.internal_disagreements/region_stats.internal_mappings\nregion_stats=region_stats.sort_values('internal_pct')\ndisplay(region_stats[['boundary_near_pct','internal_pct','valid_mappings']].round(2))\nfig,ax=plt.subplots(figsize=(5.5,max(4,0.18*len(region_stats)+1)))\ny=np.arange(len(region_stats)); ax.hlines(y,region_stats.internal_pct,region_stats.boundary_near_pct,color='#BDBDBD',linewidth=.8); ax.scatter(region_stats.internal_pct,y,s=18,color='#0072B2',label='Internal (>2 hops)',zorder=3); ax.scatter(region_stats.boundary_near_pct,y,s=18,color='#D55E00',label='Boundary-near (≤2 hops)',zorder=3); ax.set_yticks(y); ax.set_yticklabels(region_stats.index); ax.set_xlabel('Disagreement (%)'); ax.set_ylabel('Cortical region'); ax.legend(frameon=False,loc='lower right'); ax.spines[['top','right']].set_visible(False); fig.tight_layout(); plt.show()"
cells=[nbf.v4.new_markdown_cell('# Boundary disagreement QC\n\nExisting outputs are used to test whether label disagreement is concentrated near ROI boundaries or persists inside ROIs.'),nbf.v4.new_code_cell(code1),nbf.v4.new_markdown_cell('## Boundary-near versus internal disagreement\n\nBoundary-near means ≤2 native-surface hops.'),nbf.v4.new_code_cell(code2),nbf.v4.new_code_cell(code3),nbf.v4.new_markdown_cell('## Low-agreement subject × region screening'),nbf.v4.new_code_cell(code4),nbf.v4.new_markdown_cell('## Surface-hop profile'),nbf.v4.new_code_cell(code5),nbf.v4.new_markdown_cell('## Region comparison'),nbf.v4.new_code_cell(code7),nbf.v4.new_markdown_cell('## Medial-wall and unknown-label checks'),nbf.v4.new_code_cell(code6),nbf.v4.new_markdown_cell('## Interpretation\n\nBoundary-near disagreement substantially above internal disagreement supports a boundary-driven explanation. Elevated internal disagreement indicates a possible mapping, annotation, or label-assignment problem and should be visually inspected.')]
